(() => {
  'use strict';
  // ========== API RESERVED ==========
  // POST /api/auth/login — demo sign-in replacement.
  // POST /api/model/generate — video upload and Blender model generation.
  // GET /api/colors/templates — color library.
  // POST /api/prosthetic/save — save a cover.
  // POST /api/order/create — create a paid order.
  // POST /api/address/save — persist delivery address.
  // GET /api/order/list — order history.
  // GET /api/delivery/status — shipment tracking.
  const K={designs:'forme_designs_v1',orders:'forme_orders_v1',session:'forme_session_v1'};
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const get=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}, set=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
  const designs=()=>get(K.designs,[]), orders=()=>get(K.orders,[]), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const date=v=>new Intl.DateTimeFormat('en-HK',{year:'numeric',month:'short',day:'numeric'}).format(new Date(v));
  const go=p=>location.assign(p), page=document.body.dataset.page, session=get(K.session,null);
  $('.menu-toggle')?.addEventListener('click',e=>{const m=$('.nav-links'),open=m.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.setAttribute('aria-label',open?'Close menu':'Open menu')});
  if(session&&page!=='login'){const a=$('.nav-action');if(a){a.innerHTML='My Account <span aria-hidden="true">↗</span>';a.href='account.html'}}
  // TODO: API — replace the local credential check with POST /api/auth/login.
  if(page==='login') $('#login-form').addEventListener('submit',e=>{e.preventDefault();const email=$('#email').value.trim().toLowerCase(),error=$('#login-error');if(email!=='demo@forme.hk'||$('#password').value!=='123456'){error.textContent='Use the demo account shown below to sign in.';error.hidden=false;return}set(K.session,{email,signedInAt:new Date().toISOString()});const next=new URLSearchParams(location.search).get('next');go(next&&/^[a-z-]+\.html$/.test(next)?next:'account.html')});
  if(page==='create'){
    const id=new URLSearchParams(location.search).get('edit'),old=designs().find(x=>x.id===id);
    const draft={videoName:old?.videoName||'',color:old?.color||'Satin Silver',material:old?.material||'Lightweight Polymer',inspiration:old?.inspiration||'',inspirationImage:old?.inspirationImage||''};
    let step=0;const steps=$$('.wizard-step'),error=$('#wizard-error');
    if(old){$('#video-feedback').textContent=`Previously selected: ${draft.videoName}`;$('#inspiration-text').value=draft.inspiration;$('#inspiration-feedback').textContent=draft.inspirationImage?`Selected: ${draft.inspirationImage}`:''}
    const preview=()=>{$('#preview-color').textContent=draft.color;$('#preview-material').textContent=draft.material;$('#cover-preview').style.filter=({'Deep Charcoal':'brightness(.6) contrast(1.12)','Soft Sand':'sepia(.3) saturate(.8)','Ocean Blue':'sepia(.25) hue-rotate(155deg) saturate(1.4)'})[draft.color]||'none'};
    const show=i=>{step=i;steps.forEach((n,j)=>n.classList.toggle('active',j===i));$$('.wizard-progress span').forEach((n,j)=>{n.classList.toggle('active',j===i);n.classList.toggle('done',j<i)});$('#step-count').textContent=`STEP 0${i+1} / 04`;$('#prev-step').hidden=i===0;$('#next-step').innerHTML=i===3?'Save to My Prosthetic <span aria-hidden="true">↗</span>':'Continue <span aria-hidden="true">→</span>';error.hidden=true;scrollTo({top:0,behavior:'smooth'})};
    $('#video-input').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(!['video/mp4','video/quicktime','video/webm'].includes(f.type)||f.size>100*1024*1024){e.target.value='';draft.videoName='';$('#video-feedback').textContent='Choose an MP4, MOV, or WebM video under 100 MB.';return}draft.videoName=f.name;$('#video-feedback').textContent=`Selected: ${f.name}`});
    $('#sample-video').addEventListener('click',()=>{draft.videoName='Sample prosthesis video';$('#video-feedback').textContent='Sample video selected for this demo.'});
    const select=(selector,key,data)=>{$$(selector).forEach(b=>b.addEventListener('click',()=>{draft[key]=b.dataset[data];$$(selector).forEach(c=>{const on=c===b;c.classList.toggle('selected',on);c.setAttribute('aria-pressed',String(on))});preview()}));$$(selector).forEach(c=>{const on=c.dataset[data]===draft[key];c.classList.toggle('selected',on);c.setAttribute('aria-pressed',String(on))})};
    select('.color-choice','color','color');select('.material-choice','material','material');
    $('#inspiration-image').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>10*1024*1024){e.target.value='';$('#inspiration-feedback').textContent='Choose an image under 10 MB.';return}draft.inspirationImage=f.name;$('#inspiration-feedback').textContent=`Selected: ${f.name}`});
    $('#prev-step').addEventListener('click',()=>show(Math.max(0,step-1)));
    // TODO: API — POST /api/model/generate after the video step; GET /api/colors/templates for live finishes.
    // TODO: API — POST /api/prosthetic/save when the final step completes.
    $('#next-step').addEventListener('click',()=>{if(step===0&&!draft.videoName){error.textContent='Choose a video or use the sample to continue.';error.hidden=false;return}if(step<3){show(step+1);return}draft.inspiration=$('#inspiration-text').value.trim();const item={...draft,id:old?.id||(crypto.randomUUID?.()||String(Date.now())),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};set(K.designs,[item,...designs().filter(x=>x.id!==item.id)]);go('prosthetic.html')});preview();
  }
  const empty=(title,copy,url,label)=>`<div class="empty-state"><div class="empty-symbol" aria-hidden="true">◇</div><h2>${title}</h2><p>${copy}</p><a class="button button-dark" href="${url}">${label} <span aria-hidden="true">↗</span></a></div>`;
  if(page==='prosthetic'){const l=$('#design-list'),items=designs();l.innerHTML=items.length?items.map((x,i)=>`<article class="design-card"><div class="design-image"><img src="assets/cover-hero.png" alt="${esc(x.color)} cover preview" style="filter:${({'Deep Charcoal':'brightness(.6)','Soft Sand':'sepia(.3)','Ocean Blue':'sepia(.25) hue-rotate(155deg) saturate(1.4)'})[x.color]||'none'}"></div><div class="design-info"><h2>Forme Cover ${String(items.length-i).padStart(2,'0')}</h2><p>${esc(x.color)} · ${esc(x.material)}<br>Saved ${date(x.updatedAt)}</p><div class="design-actions"><a href="create.html?edit=${encodeURIComponent(x.id)}">Edit</a><a href="checkout.html?design=${encodeURIComponent(x.id)}">Pay / Order</a></div></div></article>`).join(''):empty('No covers saved yet','Create a design to see it here and place a demo order.','create.html','Create your cover')}
  const districts={'Hong Kong Island':['Central and Western','Eastern','Southern','Wan Chai'],Kowloon:['Kowloon City','Kwun Tong','Sham Shui Po','Wong Tai Sin','Yau Tsim Mong'],'New Territories':['Islands','Kwai Tsing','North','Sai Kung','Sha Tin','Tai Po','Tsuen Wan','Tuen Mun','Yuen Long']};
  // TODO: API — POST /api/address/save, then POST /api/order/create after real payment succeeds.
  if(page==='checkout'){const x=designs().find(d=>d.id===new URLSearchParams(location.search).get('design'));if(!x){$('.checkout-grid').innerHTML=empty('Choose a cover first','Save a design, then return here to place your demo order.','prosthetic.html','My Prosthetic')}else{$('#checkout-summary').innerHTML=`<h2>Your cover</h2><div class="summary-image"><img src="assets/cover-hero.png" alt="Selected prosthetic cover"></div><div class="summary-row"><span>Finish</span><strong>${esc(x.color)}</strong></div><div class="summary-row"><span>Material</span><strong>${esc(x.material)}</strong></div><div class="summary-row"><span>Price</span><strong>To be confirmed</strong></div>`;$('#region').addEventListener('change',()=>{$('#district').innerHTML='<option value="">Select district</option>'+(districts[$('#region').value]||[]).map(v=>`<option>${v}</option>`).join('')});$('#checkout-form').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const address=Object.fromEntries(new FormData(e.currentTarget).entries());const order={id:`F-${Date.now().toString(36).toUpperCase()}`,designId:x.id,color:x.color,material:x.material,address,status:'Delivered',paymentStatus:'Demo payment successful',createdAt:new Date().toISOString()};set(K.orders,[order,...orders()]);go('order.html?placed=1')})}}
  // TODO: API — GET /api/order/list for real order history.
  if(page==='order'){const l=$('#order-list'),items=orders();l.innerHTML=items.length?`${new URLSearchParams(location.search).has('placed')?'<div class="demo-payment-note"><strong>Order placed</strong><span>Demo payment successful. No money was charged.</span></div>':''}${items.map(x=>`<article class="list-card"><div class="list-thumb"><img src="assets/cover-hero.png" alt="Ordered cover"></div><div class="list-main"><span class="order-id">${esc(x.id)}</span><h2>Custom Forme Cover</h2><p>${esc(x.color)} · ${esc(x.material)}</p><p>Ordered ${date(x.createdAt)}</p></div><span class="status-pill">${esc(x.paymentStatus)}</span><a class="text-link" href="delivery.html">Delivery →</a></article>`).join('')}`:empty('No orders yet','When you place a demo order, its details will appear here.','prosthetic.html','View your covers')}
  // TODO: API — GET /api/delivery/status for carrier tracking events.
  if(page==='delivery'){const l=$('#delivery-list'),items=orders();l.innerHTML=items.length?items.map(x=>`<article class="list-card"><div class="list-thumb"><img src="assets/cover-hero.png" alt="Cover delivery"></div><div class="list-main"><span class="order-id">${esc(x.id)}</span><h2>Delivered</h2><p>${esc(x.address.district)}, Hong Kong · ${date(x.createdAt)}</p><div class="delivery-timeline" aria-label="Delivery progress"><span>Ordered</span><span>Making</span><span>Shipped</span><span>Delivered</span></div></div><span class="status-pill">Delivered · demo</span></article>`).join(''):empty('No deliveries yet','Your shipments will appear after you place an order.','prosthetic.html','View your covers')}
  if(page==='account'){const c=$('#account-content');if(!session)c.innerHTML=empty('Sign in to your account','Use the demo account to view your profile and activity.','login.html?next=account.html','Sign in');else{c.innerHTML=`<div class="account-card"><div class="account-top"><div class="avatar">F</div><div><h2>Forme Member</h2><p>${esc(session.email)}</p></div></div><div class="account-row"><span>Email</span><strong>${esc(session.email)}</strong></div><div class="account-row"><span>Saved covers</span><strong>${designs().length}</strong></div><div class="account-row"><span>Orders</span><strong>${orders().length}</strong></div><div class="account-links"><a href="prosthetic.html">My Prosthetic</a><a href="order.html">My Order</a><button type="button" id="sign-out">Sign out</button></div></div>`;$('#sign-out').addEventListener('click',()=>{localStorage.removeItem(K.session);go('index.html')})}}
  if(document.modelContext?.registerTool){try{void Promise.resolve(document.modelContext.registerTool({name:'start_cover_design',title:'Start cover design',description:'Open the Forme design studio to record a prosthesis and customize a cover.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('No inputs are accepted.');go('create.html');return{opened:'create.html'}}})).catch(()=>{})}catch{}}
})();
